with open("arrow/factory.py", "r") as f:
    lines = f.readlines()

# Check for dateutil_tz and parser.TzinfoParser usage in factory.py
for i, line in enumerate(lines):
    if "dateutil_tz" in line or "parser.TzinfoParser" in line:
        start = max(0, i-2)
        end = min(len(lines), i+3)
        for j in range(start, end):
            marker = ">>>" if j == i else "   "
            print(f"{marker} {j+1}: {lines[j]}", end='')
